def ensure_dir(p: str) -> None:
    os.makedirs(p, exist_ok=True)


def log(logf, msg: str) -> None:
    line = f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {msg}"
    print(line)
    if logf:
        logf.write(line + "\n")
        logf.flush()


def sigmoid(x: np.ndarray) -> np.ndarray:
    """Numerically stable sigmoid via scipy.special.expit."""
    return _stable_sigmoid(x).astype(np.float32)


# ══════════════════════════════════════════════════════════════════════════════
# Parse INPUT_DIR
# ══════════════════════════════════════════════════════════════════════════════

def parse_input_dir(input_dir: str) -> dict:
    """
    從 INPUT_DIR 解析所有路徑元件。

    Required structure:
      <MULTIMODAL_OUTPUT_ROOT>/training/<model_name>/MULTIMODAL/<run_tag>/Best_fold{N}

    Path parents mapping（从 leaf 往上數）：
      p              = .../Multimodal_outputs/training/swin_tiny/MULTIMODAL/<run_tag>/Best_foldN
      p.parents[0]   = .../Multimodal_outputs/training/swin_tiny/MULTIMODAL/<run_tag>
      p.parents[1]   = .../Multimodal_outputs/training/swin_tiny/MULTIMODAL
      p.parents[2]   = .../Multimodal_outputs/training/swin_tiny
      p.parents[3]   = .../Multimodal_outputs/training
      p.parents[4]   = .../Multimodal_outputs               ← multimodal_out_root
    """
    p = Path(input_dir).resolve()
    if not p.is_dir():
        raise FileNotFoundError(f"INPUT_DIR not found: {input_dir}")

    leaf = p.name
    if not leaf.startswith("Best_fold"):
        raise ValueError(
            f"INPUT_DIR must end with 'Best_fold{{N}}', got: '{leaf}'"
        )
    try:
        best_fold = int(leaf.replace("Best_fold", ""))
    except ValueError:
        raise ValueError(f"Cannot parse fold number from '{leaf}'.")

    run_tag             = p.parents[0].name   # <run_tag>
    modality_from_path  = p.parents[1].name   # should be "MULTIMODAL"
    model_name          = p.parents[2].name   # e.g. "swin_tiny"
    training_dir        = p.parents[3].name   # should be "training"
    multimodal_out_root = p.parents[4]        # ★ 修正①：p.parents[4] 才是 Multimodal_outputs

    # 路徑結構驗證（提早報錯）
    if training_dir != "training":
        raise ValueError(
            f"INPUT_DIR path structure error: expected parent folder 'training', "
            f"got '{training_dir}'.\n"
            f"Required: <MULTIMODAL_OUTPUT_ROOT>/training/<model>/{MODALITY}/<run_tag>/Best_fold{{N}}"
        )
    if modality_from_path != MODALITY:
        raise ValueError(
            f"Parsed modality from path='{modality_from_path}'，"
            f"但本腳本固定 MODALITY='{MODALITY}'。請確認 INPUT_DIR 路徑結構。"
        )

    return {
        "input_dir":              str(p),
        "model_name":             model_name,
        "modality":               MODALITY,
        "run_tag":                run_tag,
        "best_fold":              best_fold,
        "multimodal_output_root": multimodal_out_root,
    }


# ══════════════════════════════════════════════════════════════════════════════
# Resolve checkpoint path
# ══════════════════════════════════════════════════════════════════════════════

def resolve_checkpoint_path(
    checkpoint_root: str,
    model_name: str,
    run_tag: str,
    best_fold: int,
) -> str:
    """
    訓練腳本儲存路徑：
      Primary  : CHECKPOINT_ROOT/<model>/MULTIMODAL/<run_tag>/Best_fold{N}/model_best.pth
      Fallback : CHECKPOINT_ROOT/<model>/MULTIMODAL/<run_tag>/Kfold/fold{N}/model_best.pth
    """
    base     = os.path.join(checkpoint_root, model_name, MODALITY, run_tag)
    primary  = os.path.join(base, f"Best_fold{best_fold}", "model_best.pth")
    fallback = os.path.join(base, "Kfold", f"fold{best_fold}", "model_best.pth")

    if os.path.isfile(primary):
        return primary
    if os.path.isfile(fallback):
        return fallback

    raise FileNotFoundError(
        f"model_best.pth 找不到。\n"
        f"  Primary  : {primary}\n"
        f"  Fallback : {fallback}\n"
        f"  CHECKPOINT_ROOT = {checkpoint_root}\n\n"
        f"請確認 CHECKPOINT_ROOT 是否正確指向 Multimodal_outputs/checkpoints，"
        f"而非舊的 singlemode checkpoints 目錄。"
    )


# ══════════════════════════════════════════════════════════════════════════════
# Load fold_summary.json
# ══════════════════════════════════════════════════════════════════════════════

def load_fold_summary(input_dir: str, parsed: dict) -> Tuple[float, dict]:
    """
    讀取 INPUT_DIR/fold_summary.json，驗證 fold / modality / model_name 與路徑一致。
    回傳 (temperature, summary_dict)。
    """
    summary_path = os.path.join(input_dir, "fold_summary.json")
    if not os.path.isfile(summary_path):
        raise FileNotFoundError(
            f"fold_summary.json not found: {summary_path}\n"
            "請確認 New_2class_Swin_train_multimodal_oof.py 已完整執行。"
        )
    with open(summary_path, encoding="utf-8") as fh:
        summary = json.load(fh)

    errs = []
    if int(summary["fold"]) != parsed["best_fold"]:
        errs.append(
            f"  fold: path=Best_fold{parsed['best_fold']}, "
            f"JSON fold={summary['fold']}"
        )
    if str(summary.get("modality", "")) != parsed["modality"]:
        errs.append(
            f"  modality: path='{parsed['modality']}', "
            f"JSON='{summary.get('modality')}'"
        )
    if str(summary.get("model_name", "")) != parsed["model_name"]:
        errs.append(
            f"  model_name: path='{parsed['model_name']}', "
            f"JSON='{summary.get('model_name')}'"
        )
    if errs:
        raise ValueError(
            "INPUT_DIR 與 fold_summary.json 不一致：\n" + "\n".join(errs)
        )

    return float(summary["temperature"]), summary


# ══════════════════════════════════════════════════════════════════════════════
# Data loading
# ══════════════════════════════════════════════════════════════════════════════

def normalize_manifest_dtypes(df: pd.DataFrame) -> pd.DataFrame:
    """與訓練腳本的 normalize_manifest_dtypes 完全一致。"""
    out = df.copy()
    for col in ["exam_key", "patient_id", "eye", "exam_date", "split_set"]:
        if col in out.columns:
            out[col] = out[col].astype(str)
    if "y_true" in out.columns:
        out["y_true"] = pd.to_numeric(out["y_true"], errors="coerce")
    for col in ["has_oct0", "has_oct1", "has_octa3", "label_conflict", "fold_id"]:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce")
    return out


def load_test_dataframe(manifest_csv: str, logf) -> pd.DataFrame:
    """
    讀取 multimodal_manifest.csv，回傳 split_set=='test' 的 rows。

    套用與訓練腳本相同的篩選條件：
      1. label_conflict == 0
      2. y_true not null
      3. oct0_image_path not null / not empty（合併影像路徑）
      4. split_set == 'test'
    """
    required_cols = [
        "exam_key", "patient_id", "split_set", "y_true",
        "label_conflict", "has_oct0", MULTIMODAL_IMG_COL,
    ]

    df = pd.read_csv(manifest_csv)
    df = normalize_manifest_dtypes(df)

    missing = [c for c in required_cols if c not in df.columns]
    if missing:
        raise ValueError(
            f"multimodal_manifest.csv 缺少必要欄位：{missing}\nFile: {manifest_csv}"
        )

    n_raw = len(df)

    df = df[df["label_conflict"] == 0].copy()
    log(logf, f"  After label_conflict==0               : {len(df)} / {n_raw} rows")

    df = df[df["y_true"].notna()].copy()
    log(logf, f"  After y_true notna                    : {len(df)} rows")

    df = df[
        df[MULTIMODAL_IMG_COL].notna() &
        (df[MULTIMODAL_IMG_COL].astype(str).str.strip() != "")
    ].copy()
    log(logf, f"  After {MULTIMODAL_IMG_COL} not-null   : {len(df)} rows")

    for split in ["train_valid", "test"]:
        n = int((df["split_set"] == split).sum())
        log(logf, f"  split_set='{split}' available         : {n} rows")

    df = df[df["split_set"] == "test"].copy().reset_index(drop=True)

    if len(df) == 0:
        raise RuntimeError(
            "篩選後無 test rows。請確認 multimodal_manifest.csv 含 split_set=='test' rows。"
        )

    # 硬性保證：絕對不允許 train_valid row 進入 metric 計算
    assert (df["split_set"] == "train_valid").sum() == 0, \
        "DATA LEAKAGE: train_valid rows found in test DataFrame — abort."

    return df


# ══════════════════════════════════════════════════════════════════════════════
# Model factory
# ══════════════════════════════════════════════════════════════════════════════

def build_model(model_name: str) -> nn.Module:
    """
    建立 num_classes=1 模型（single sigmoid head，output [B,1]）。
    img_size=(IMG_H, IMG_W) = (448, 224) 必須傳入，讓 Swin patch_embed
    正確計算非正方形輸入的 window position embedding。
    """
    if model_name not in TIMM_MODEL_MAP:
        raise NotImplementedError(
            f"model_name='{model_name}' 不在 TIMM_MODEL_MAP。"
            f"已登錄：{list(TIMM_MODEL_MAP.keys())}"
        )
    return timm.create_model(
        TIMM_MODEL_MAP[model_name],
        pretrained=False,
        num_classes=1,
        img_size=(IMG_H, IMG_W),   # ★ (448, 224)，對應訓練時設定
    )


def load_checkpoint(
    model: nn.Module, ckpt_path: str, device: torch.device,
) -> nn.Module:
    """讀取 model_best.pth（訓練腳本儲存格式）。"""
    raw = torch.load(ckpt_path, map_location=device, weights_only=False)
    if isinstance(raw, dict):
        if "model_state_dict" in raw:
            state_dict = raw["model_state_dict"]
        elif "state_dict" in raw:
            state_dict = raw["state_dict"]
        else:
            state_dict = raw
    else:
        state_dict = raw

    model.load_state_dict(state_dict, strict=True)
    model.to(device)
    model.eval()
    return model


# ══════════════════════════════════════════════════════════════════════════════
# Dataset
# ══════════════════════════════════════════════════════════════════════════════

class MultimodalTestDataset(Dataset):
    """
    讀取 multimodal_manifest.csv test rows。
    影像路徑來自 oct0_image_path（224×448 合併影像）。
    任何讀圖失敗直接 raise RuntimeError，不靜默略過。
    """

    def __init__(self, df: pd.DataFrame, transform) -> None:
        self.records   = df[["exam_key", "y_true", MULTIMODAL_IMG_COL]].copy()
        self.transform = transform

    def __len__(self) -> int:
        return len(self.records)

    def __getitem__(self, idx: int):
        row      = self.records.iloc[idx]
        label    = int(row["y_true"])
        exam_key = str(row["exam_key"])
        img_path = str(row[MULTIMODAL_IMG_COL])
        try:
            img = Image.open(img_path).convert("RGB")
        except Exception as e:
            raise RuntimeError(
                f"Failed to read multimodal image: {img_path} "
                f"({type(e).__name__}: {e})"
            )
        if self.transform:
            img = self.transform(img)
        return img, label, exam_key


def get_test_transform() -> transforms.Compose:
    """
    ★ resize 改為 (IMG_H, IMG_W) = (448, 224)，與訓練 tf_val 完全一致。
    無 augmentation。
    """
    return transforms.Compose([
        transforms.Resize((IMG_H, IMG_W)),
        transforms.ToTensor(),
        transforms.Normalize(
            mean=[0.485, 0.456, 0.406],
            std =[0.229, 0.224, 0.225],
        ),
    ])


# ══════════════════════════════════════════════════════════════════════════════
# Inference
# ══════════════════════════════════════════════════════════════════════════════

@torch.no_grad()
def run_inference(
    model: nn.Module,
    loader: DataLoader,
    device: torch.device,
    logf,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    """
    回傳 (exam_keys, y_true, logits_uncal)。
    model output [B,1] → squeeze(1) → scalar logit [B]。
    """
    all_keys, all_labels, all_logits = [], [], []
    model.eval()
    n_batches = len(loader)

    for i, (imgs, labels, keys) in enumerate(loader):
        imgs        = imgs.to(device)
        out         = model(imgs)                      # [B, 1]
        logits_flat = out.squeeze(1).cpu().numpy()     # [B]

        all_keys.extend(keys)
        all_labels.extend(labels.numpy())
        all_logits.append(logits_flat)

        if (i + 1) % max(1, n_batches // 5) == 0:
            log(logf, f"  Inference: {i+1}/{n_batches} batches done")

    return (
        np.array(all_keys),
        np.array(all_labels, dtype=np.int32),
        np.concatenate(all_logits).astype(np.float32),
    )


# ══════════════════════════════════════════════════════════════════════════════
# Temperature Scaling
# ══════════════════════════════════════════════════════════════════════════════

def apply_temperature_scaling(
    logits: np.ndarray, temperature: float,
) -> Tuple[np.ndarray, np.ndarray]:
    """
    logit_calib = logit / T*
    prob_calib  = sigmoid(logit_calib)

    T* 由訓練腳本在 validation set 上以 LBFGS 最小化 NLL fitting，
    此處直接從 fold_summary.json 載入，不重新 fitting。
    Ref: Guo et al. (2017). On Calibration of Modern Neural Networks. ICML.
    """
    if temperature <= 0:
        raise ValueError(f"Temperature must be > 0, got {temperature}")
    lc = (logits / temperature).astype(np.float32)
    return lc, sigmoid(lc).astype(np.float32)


# ══════════════════════════════════════════════════════════════════════════════
# ECE
# ══════════════════════════════════════════════════════════════════════════════

def compute_ece(
    y_true: np.ndarray, y_prob: np.ndarray, n_bins: int = 10,
) -> Tuple[float, List[dict]]:
    """
    ECE = Σ_b (|B_b|/N) |acc(B_b) − conf(B_b)|  (equal-width bins)

    切割方式：[0, 0.1), [0.1, 0.2), ..., [0.9, 1.0]（最後一個含右端點）。
    空 bin 不計入 ECE，但仍保留在 bins_data（accuracy=None）。
    Ref: Guo et al. (2017), ICML, eq.(3).
    """
    bin_edges = np.linspace(0.0, 1.0, n_bins + 1)
    total_n   = len(y_true)
    ece, bins_data = 0.0, []

    for i in range(n_bins):
        lo, hi = bin_edges[i], bin_edges[i + 1]
        mask   = (y_prob >= lo) & (y_prob < hi)
        if i == n_bins - 1:
            mask |= (y_prob == hi)
        n_bin = int(mask.sum())
        if n_bin == 0:
            bins_data.append({
                "lower": lo, "upper": hi, "n": 0,
                "accuracy": None, "confidence": None,
            })
            continue
        acc  = float(y_true[mask].mean())
        conf = float(y_prob[mask].mean())
        ece += (n_bin / total_n) * abs(acc - conf)
        bins_data.append({
            "lower": lo, "upper": hi, "n": n_bin,
            "accuracy": acc, "confidence": conf,
        })
    return float(ece), bins_data


# ══════════════════════════════════════════════════════════════════════════════
# Metrics
# ══════════════════════════════════════════════════════════════════════════════

def _cls_metrics(
    y_true: np.ndarray, y_pred: np.ndarray,
    y_prob: np.ndarray, prefix: str,
) -> dict:
    """
    完整二元分類 metrics（pos_label=1 即 active）：

    Confusion matrix 定義：
      TP : predicted active,   truly active
      FP : predicted active,   truly inactive
      FN : predicted inactive, truly active
      TN : predicted inactive, truly inactive

    公式：
      Sensitivity (Recall) = TP / (TP + FN)
      Specificity          = TN / (TN + FP)
      PPV (Precision)      = TP / (TP + FP)
      NPV                  = TN / (TN + FN)   ← rule-out safety
      F1 (active)          = 2·PPV·Sens / (PPV+Sens) = 2TP/(2TP+FP+FN)
      Balanced Accuracy    = (Sensitivity + Specificity) / 2
      Brier Score          = mean((prob − y_true)²)
    """
    tn, fp, fn, tp = confusion_matrix(y_true, y_pred, labels=[0, 1]).ravel()
    sens = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    spec = tn / (tn + fp) if (tn + fp) > 0 else 0.0
    ppv  = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    npv  = tn / (tn + fn) if (tn + fn) > 0 else 0.0

    return {
        f"{prefix}_auroc":        float(roc_auc_score(y_true, y_prob)),
        f"{prefix}_auprc":        float(average_precision_score(y_true, y_prob)),
        f"{prefix}_balanced_acc": float(balanced_accuracy_score(y_true, y_pred)),
        f"{prefix}_sensitivity":  float(sens),
        f"{prefix}_specificity":  float(spec),
        f"{prefix}_ppv":          float(ppv),
        f"{prefix}_npv":          float(npv),
        f"{prefix}_f1_active":    float(f1_score(y_true, y_pred,
                                                  pos_label=1, average="binary")),
        f"{prefix}_f1_macro":     float(f1_score(y_true, y_pred, average="macro")),
        f"{prefix}_accuracy":     float(accuracy_score(y_true, y_pred)),
        f"{prefix}_brier":        float(brier_score_loss(y_true, y_prob)),
        f"{prefix}_TP": int(tp), f"{prefix}_FP": int(fp),
        f"{prefix}_FN": int(fn), f"{prefix}_TN": int(tn),
    }


def compute_all_metrics(
    y_true: np.ndarray,
    logits_uncal: np.ndarray,
    temperature: float,
    threshold: float = 0.5,
    ece_n_bins: int  = 10,
) -> Tuple[dict, List[dict], List[dict]]:
    """
    計算 uncalibrated 與 calibrated（post-TS）兩組 metrics。

    流程：
      prob_uncal  = sigmoid(logits_uncal)
      logit_calib = logits_uncal / T*
      prob_calib  = sigmoid(logit_calib)
      y_pred      = (prob >= threshold).astype(int)
    """
    if len(np.unique(y_true)) < 2:
        raise RuntimeError(
            "Test set 只有一個 class，AUROC 無法計算。"
            "請確認 independent test split 包含兩個 class。"
        )

    prob_uncal           = sigmoid(logits_uncal)
    logits_cal, prob_cal = apply_temperature_scaling(logits_uncal, temperature)

    y_pred_uncal = (prob_uncal >= threshold).astype(int)
    y_pred_cal   = (prob_cal   >= threshold).astype(int)

    m_uncal = _cls_metrics(y_true, y_pred_uncal, prob_uncal, "uncal")
    m_calib = _cls_metrics(y_true, y_pred_cal,   prob_cal,   "calib")

    ece_uncal, bins_uncal = compute_ece(y_true, prob_uncal, ece_n_bins)
    ece_calib, bins_calib = compute_ece(y_true, prob_cal,   ece_n_bins)

    n_total    = len(y_true)
    n_active   = int((y_true == 1).sum())
    n_inactive = int((y_true == 0).sum())

    return {
        "n_total":         n_total,
        "n_active":        n_active,
        "n_inactive":      n_inactive,
        "imbalance_ratio": round(n_inactive / n_active, 2) if n_active > 0 else None,
        "threshold":       threshold,
        "temperature":     temperature,
        "ece_n_bins":      ece_n_bins,
        "ece_uncal":       ece_uncal,
        "ece_calib":       ece_calib,
        "ece_reduction":   ece_uncal - ece_calib,   # > 0 表示 TS 改善校準
        **m_uncal,
        **m_calib,
    }, bins_uncal, bins_calib


