def save_curve_csv(
    col1: np.ndarray, col2: np.ndarray, col3: np.ndarray,
    col_names: List[str], out_path: str,
) -> None:
    n = len(col1)
    if len(col3) == n - 1:
        col3 = np.append(col3, np.nan)
    pd.DataFrame({col_names[0]: col1, col_names[1]: col2,
                  col_names[2]: col3}).to_csv(
        out_path, index=False, encoding="utf-8-sig", float_format="%.6f")


def save_calibration_csv(
    bins_uncal: List[dict], bins_calib: List[dict], out_path: str,
) -> None:
    rows = []
    for bu, bc in zip(bins_uncal, bins_calib):
        rows.append({
            "bin_lower": bu["lower"], "bin_upper": bu["upper"],
            "bin_mid":   (bu["lower"] + bu["upper"]) / 2,
            "n_uncal":    bu["n"],    "acc_uncal":  bu["accuracy"],
            "conf_uncal": bu["confidence"],
            "n_calib":    bc["n"],    "acc_calib":  bc["accuracy"],
            "conf_calib": bc["confidence"],
        })
    pd.DataFrame(rows).to_csv(
        out_path, index=False, encoding="utf-8-sig", float_format="%.6f")


def save_test_preds_csv(
    df_test: pd.DataFrame,
    logits_uncal: np.ndarray,
    temperature: float,
    out_path: str,
) -> None:
    """
    ★ 修正③：接收 df_test，保留 source tracing 欄位。
    供 meta-learner 使用，同時支援 FP/FN 分析與 Grad-CAM 追蹤。

    輸出欄位：
      exam_key, patient_id, eye, exam_date, split_set, fold_id, y_true,
      oct0_image_path（合併影像路徑）,
      src_oct0_path, src_oct1_path, chosen_oct_type（原始 OCT 追蹤）,
      src_oct_path, src_octa3_path（原始來源路徑）,
      logit_uncal, prob_uncal, temperature, logit_calib, prob_calib
    """
    prob_uncal           = sigmoid(logits_uncal)
    logits_cal, prob_cal = apply_temperature_scaling(logits_uncal, temperature)

    out = df_test.copy().reset_index(drop=True)
    out["logit_uncal"] = logits_uncal
    out["prob_uncal"]  = prob_uncal
    out["temperature"] = temperature
    out["logit_calib"] = logits_cal
    out["prob_calib"]  = prob_cal

    keep_cols = [
        # 基本 metadata
        "exam_key", "patient_id", "eye", "exam_date",
        "split_set", "fold_id", "y_true",
        # 合併影像路徑
        MULTIMODAL_IMG_COL,
        # OCT source tracing（來自 Build 腳本）
        "src_oct0_path", "src_oct1_path", "chosen_oct_type",
        "src_oct_path",  "src_octa3_path",
        # 預測結果
        "logit_uncal", "prob_uncal",
        "temperature", "logit_calib", "prob_calib",
    ]
    keep_cols = [c for c in keep_cols if c in out.columns]
    out[keep_cols].to_csv(
        out_path, index=False, encoding="utf-8-sig", float_format="%.6f"
    )


