def log_summary_table(logf, metrics: dict, model_name: str) -> None:
    SEP = "─" * 70
    log(logf, SEP)
    log(logf, f"SUMMARY TABLE  —  {model_name.upper()} / {MODALITY} "
              f"({IMG_W}×{IMG_H})  threshold={metrics['threshold']:.2f}")
    log(logf, SEP)
    log(logf, f"  {'Metric':<22}  {'Uncalib':>10}  {'Calibrated':>12}")
    log(logf, f"  {'─'*22}  {'─'*10}  {'─'*12}")
    for label, key in [
        ("AUROC",             "auroc"),
        ("AUPRC",             "auprc"),
        ("Balanced Accuracy", "balanced_acc"),
        ("Sensitivity",       "sensitivity"),
        ("Specificity",       "specificity"),
        ("PPV",               "ppv"),
        ("NPV",               "npv"),
        ("F1 (active)",       "f1_active"),
        ("F1 (macro)",        "f1_macro"),
        ("Accuracy",          "accuracy"),
        ("Brier Score",       "brier"),
    ]:
        log(logf, f"  {label:<22}  "
                  f"{metrics[f'uncal_{key}']:>10.4f}  "
                  f"{metrics[f'calib_{key}']:>12.4f}")
    log(logf, f"  {'─'*22}  {'─'*10}  {'─'*12}")
    log(logf, f"  {'ECE':<22}  "
              f"{metrics['ece_uncal']:>10.4f}  "
              f"{metrics['ece_calib']:>12.4f}")
    log(logf, SEP)
    log(logf, f"  Confusion Matrix (calib):  "
              f"TP={metrics['calib_TP']}  FP={metrics['calib_FP']}  "
              f"FN={metrics['calib_FN']}  TN={metrics['calib_TN']}")
    log(logf, SEP)


def write_report(metrics: dict, run_cfg: dict, out_path: str) -> None:
    sep  = "=" * 72
    sep2 = "─" * 72
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(f"{sep}\n")
        f.write("MULTIMODAL BASE MODEL — INDEPENDENT TEST SET EVALUATION REPORT\n")
        f.write(f"{sep}\n\n")

        f.write("[RUN CONFIG]\n")
        for k, v in run_cfg.items():
            f.write(f"  {k:<36}: {v}\n")

        n, na, ni = metrics["n_total"], metrics["n_active"], metrics["n_inactive"]
        f.write("\n[TEST SET COMPOSITION]\n")
        f.write(f"  Total    : {n}\n")
        f.write(f"  Active   : {na}  ({na/n*100:.1f}%)\n")
        f.write(f"  Inactive : {ni}  ({ni/n*100:.1f}%)\n")
        _imb = metrics["imbalance_ratio"]
        f.write(f"  Imbalance: {f'{_imb:.2f}:1' if _imb is not None else 'undefined'}\n")

        f.write("\n[TEMPERATURE SCALING]\n")
        f.write(f"  T* (val set)  : {metrics['temperature']:.6f}\n")
        f.write(f"  ECE uncal     : {metrics['ece_uncal']:.4f}\n")
        f.write(f"  ECE calib     : {metrics['ece_calib']:.4f}\n")
        d = "↓ improved" if metrics["ece_reduction"] > 0 else "↑ worsened"
        f.write(f"  ECE Δ         : {metrics['ece_reduction']:.4f}  ({d})\n")
        f.write(f"  Brier uncal   : {metrics['uncal_brier']:.4f}\n")
        f.write(f"  Brier calib   : {metrics['calib_brier']:.4f}\n")

        f.write("\n[METRIC FORMULAS]\n")
        f.write(f"  Sensitivity       = TP / (TP + FN)\n")
        f.write(f"  Specificity       = TN / (TN + FP)\n")
        f.write(f"  PPV               = TP / (TP + FP)\n")
        f.write(f"  NPV               = TN / (TN + FN)\n")
        f.write(f"  F1 (active)       = 2·PPV·Sensitivity / (PPV + Sensitivity)\n")
        f.write(f"  Balanced Accuracy = (Sensitivity + Specificity) / 2\n")
        f.write(f"  Brier Score       = mean((prob - y_true)^2)\n")
        f.write(f"  ECE               = Σ_b (|B_b|/N)|acc(B_b) - conf(B_b)|\n")
        f.write(f"  AUROC             = Area Under ROC Curve (threshold-free)\n")
        f.write(f"  AUPRC             = Σ_k (R_k - R_{{k-1}}) × P_k\n")

        f.write("\n[1. DISCRIMINATIVE PERFORMANCE]\n")
        f.write(f"  {'Metric':<25}  {'Uncalib':>10}  {'Calibrated':>12}\n")
        f.write(f"  {'-'*25}  {'-'*10}  {'-'*12}\n")
        for m in ["auroc", "auprc"]:
            f.write(f"  {m.upper():<25}  "
                    f"{metrics[f'uncal_{m}']:>10.4f}  "
                    f"{metrics[f'calib_{m}']:>12.4f}\n")

        f.write(f"\n[2. THRESHOLD-BASED METRICS  (thr={metrics['threshold']:.2f})]\n")
        f.write(f"  {'Metric':<25}  {'Uncalib':>10}  {'Calibrated':>12}\n")
        f.write(f"  {'-'*25}  {'-'*10}  {'-'*12}\n")
        for m, lbl in [
            ("balanced_acc", "Balanced Accuracy"),
            ("sensitivity",  "Sensitivity"),
            ("specificity",  "Specificity"),
            ("ppv",          "PPV"),
            ("npv",          "NPV"),
            ("f1_active",    "F1 (active)"),
            ("f1_macro",     "F1 (macro)"),
            ("accuracy",     "Accuracy"),
        ]:
            f.write(f"  {lbl:<25}  "
                    f"{metrics[f'uncal_{m}']:>10.4f}  "
                    f"{metrics[f'calib_{m}']:>12.4f}\n")

        f.write("\n[3. CLINICAL SAFETY METRICS  (calibrated)]\n")
        f.write(f"  PPV (active)    : {metrics['calib_ppv']:.4f}\n")
        f.write(f"  NPV (inactive)  : {metrics['calib_npv']:.4f}  ← rule-out safety\n")
        f.write(f"  Balanced Acc    : {metrics['calib_balanced_acc']:.4f}\n")
        f.write("\n  Confusion Matrix (calibrated):\n")
        f.write( "                        Pred active   Pred inactive\n")
        f.write(f"    True active      {metrics['calib_TP']:>12}  "
                f"{metrics['calib_FN']:>14}\n")
        f.write(f"    True inactive    {metrics['calib_FP']:>12}  "
                f"{metrics['calib_TN']:>14}\n")

        f.write("\n[4. CALIBRATION QUALITY]\n")
        f.write(f"  ECE  : {metrics['ece_uncal']:.4f} → {metrics['ece_calib']:.4f}\n")
        f.write(f"  Brier: {metrics['uncal_brier']:.4f} → {metrics['calib_brier']:.4f}\n")

        f.write(f"\n{sep2}\n")
        f.write("SUMMARY TABLE  (calibrated, post-TS)\n")
        f.write(f"{sep2}\n")
        f.write(f"  {'Metric':<22}  {'Value':>10}\n")
        f.write(f"  {'-'*22}  {'-'*10}\n")
        for lbl, key in [
            ("AUROC",             "calib_auroc"),
            ("AUPRC",             "calib_auprc"),
            ("Balanced Accuracy", "calib_balanced_acc"),
            ("Sensitivity",       "calib_sensitivity"),
            ("Specificity",       "calib_specificity"),
            ("PPV",               "calib_ppv"),
            ("NPV",               "calib_npv"),
            ("F1 (active)",       "calib_f1_active"),
            ("F1 (macro)",        "calib_f1_macro"),
            ("Accuracy",          "calib_accuracy"),
            ("ECE",               "ece_calib"),
            ("Brier",             "calib_brier"),
        ]:
            f.write(f"  {lbl:<22}  {metrics[key]:>10.4f}\n")
        f.write(f"{sep2}\n")

        f.write("\n[REFERENCES]\n")
        f.write("  AUROC/AUPRC : Saito & Rehmsmeier, PLOS ONE 2015\n")
        f.write("    https://doi.org/10.1371/journal.pone.0118432\n")
        f.write("  ECE / TS    : Guo et al., ICML 2017\n")
        f.write("    https://proceedings.mlr.press/v70/guo17a.html\n")
        f.write("  NPV Clinical: STARD-AI, Nature Medicine 2020\n")
        f.write("    https://doi.org/10.1038/s41591-020-0941-1\n")

        f.write("\n[OUTPUT FILES]\n")
        for fname in [
            "confusion_matrix.png",
            "roc_curve.png",
            "pr_curve.png",
            "reliability_diagram.png",
            "test_metrics.csv         (tall-format: one row per metric)",
            "test_summary.json        (structured summary with formulas & references)",
            "roc_data.csv",
            "pr_data.csv",
            "calibration_data.csv",
            "test_preds.csv           (KEY: src tracing + predictions, for meta-learner)",
            "test_evaluation_report.txt",
            "test_evaluation.log",
        ]:
            f.write(f"  {fname}\n")


# ══════════════════════════════════════════════════════════════════════════════
# MAIN
# ══════════════════════════════════════════════════════════════════════════════

def main() -> None:
    torch.manual_seed(RANDOM_SEED)
    np.random.seed(RANDOM_SEED)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # ── Step 0: Parse INPUT_DIR ───────────────────────────────────────────────
    parsed    = parse_input_dir(INPUT_DIR)
    model_name = parsed["model_name"]
    run_tag    = parsed["run_tag"]
    best_fold  = parsed["best_fold"]

    ckpt_path = resolve_checkpoint_path(CHECKPOINT_ROOT, model_name, run_tag, best_fold)

    out_dir = os.path.join(
        TEST_EVAL_ROOT, model_name, MODALITY, run_tag, f"Best_fold{best_fold}",
    )
    ensure_dir(out_dir)

    temperature, fold_summary = load_fold_summary(INPUT_DIR, parsed)

    logf = open(
        os.path.join(out_dir, "test_evaluation.log"),
        "a", buffering=1, encoding="utf-8"
    )

    print(f"\n{'='*72}")
    print(f"  MULTIMODAL BASE MODEL TEST EVALUATION")
    print(f"  {model_name.upper()} / {MODALITY} ({IMG_W}×{IMG_H}) / fold {best_fold}")
    print(f"  INPUT_DIR: {INPUT_DIR}")
    print(f"{'='*72}")

    log(logf, "=" * 72)
    log(logf, "MULTIMODAL BASE MODEL TEST EVALUATION")
    log(logf, f"  model_name           : {model_name}")
    log(logf, f"  modality             : {MODALITY} ({IMG_W}×{IMG_H}, OCT top / OCTA3 bottom)")
    log(logf, f"  run_tag              : {run_tag}")
    log(logf, f"  best_fold            : {best_fold}")
    log(logf, f"  INPUT_DIR            : {INPUT_DIR}")
    log(logf, f"  multimodal_manifest  : {MULTIMODAL_MANIFEST_CSV}")
    log(logf, f"  checkpoint           : {ckpt_path}")
    log(logf, f"  out_dir              : {out_dir}")
    log(logf, f"  device               : {device}")
    log(logf, f"  timm_model           : {TIMM_MODEL_MAP[model_name]}  img_size=({IMG_H},{IMG_W})")
    log(logf, f"  num_classes          : 1  (single sigmoid head, output [B,1])")
    log(logf, f"  temperature T*       : {temperature:.6f}  (from val set, LBFGS NLL fitting)")
    nll_before = fold_summary.get("nll_before_ts")
    nll_after  = fold_summary.get("nll_after_ts")
    if nll_before is not None:
        log(logf, f"  NLL before TS        : {nll_before:.6f}")
    if nll_after is not None:
        log(logf, f"  NLL after  TS        : {nll_after:.6f}")
    log(logf, f"  best_val_bce         : {fold_summary.get('best_val_bce', 'n/a')}")
    log(logf, f"  best_val_auc         : {fold_summary.get('best_val_auc', 'n/a')}")
    log(logf, f"  best_epoch           : {fold_summary.get('best_epoch', 'n/a')}")

    # ── Step 1: Load test data ────────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 1: Load test split from multimodal_manifest.csv")
    log(logf, f"  Filters: label_conflict==0 → y_true notna → "
              f"{MULTIMODAL_IMG_COL} notna → split_set=='test'")

    df_test  = load_test_dataframe(MULTIMODAL_MANIFEST_CSV, logf)
    n_test   = len(df_test)
    n_active = int((df_test["y_true"] == 1).sum())
    n_inact  = int((df_test["y_true"] == 0).sum())
    _imb_str = f"{n_inact/n_active:.2f}:1" if n_active > 0 else "undefined"
    log(logf, f"  Test set final : {n_test} samples  "
              f"active={n_active} ({n_active/n_test*100:.1f}%)  "
              f"inactive={n_inact} ({n_inact/n_test*100:.1f}%)  "
              f"imbalance={_imb_str}")

    # ── Step 2: Build model and load checkpoint ───────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 2: Build model and load checkpoint")

    model = build_model(model_name)

    # dummy forward 確認 448×224 可通過
    model.eval()
    with torch.no_grad():
        dummy     = torch.randn(1, 3, IMG_H, IMG_W)
        dummy_out = model(dummy)
    if dummy_out.shape != (1, 1):
        raise RuntimeError(
            f"Dummy forward shape 不符：{dummy_out.shape}，期望 (1,1)。"
            f"請確認 timm model 支援 img_size=({IMG_H},{IMG_W})。"
        )

    model = load_checkpoint(model, ckpt_path, device)
    log(logf, f"  Model ready: {TIMM_MODEL_MAP[model_name]}  "
              f"img_size=({IMG_H},{IMG_W})  num_classes=1  output=[B,1]")

    # ── Step 3: DataLoader ────────────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 3: Create DataLoader")

    test_ds = MultimodalTestDataset(df_test, get_test_transform())
    test_loader = DataLoader(
        test_ds, batch_size=BATCH_SIZE, shuffle=False,
        num_workers=NUM_WORKERS, pin_memory=(device.type == "cuda"),
    )
    log(logf, f"  DataLoader: {len(test_ds)} samples  "
              f"{len(test_loader)} batches  bs={BATCH_SIZE}")

    # ── Step 4: Inference ─────────────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 4: Inference")

    if device.type == "cuda":
        torch.cuda.synchronize()
    start = time.perf_counter()

    exam_keys, y_true, logits_uncal = run_inference(model, test_loader, device, logf)

    if device.type == "cuda":
        torch.cuda.synchronize()
    elapsed = time.perf_counter() - start

    # ── Safety check: ensure inference order matches df_test metadata ─────────
    # This is important because save_test_preds_csv() appends logits directly
    # to df_test.copy(). If the order is mismatched, predictions would be
    # assigned to the wrong exam/patient.
    expected_keys = df_test["exam_key"].astype(str).to_numpy()
    returned_keys = exam_keys.astype(str)

    if len(returned_keys) != len(expected_keys):
        raise RuntimeError(
            "exam_key length mismatch between DataLoader output and df_test.\n"
            f"  len(returned_keys) = {len(returned_keys)}\n"
            f"  len(expected_keys) = {len(expected_keys)}"
        )

    if not np.array_equal(returned_keys, expected_keys):
        mismatch_idx = np.where(returned_keys != expected_keys)[0]
        examples = []
        for idx in mismatch_idx[:10]:
            examples.append({
                "index": int(idx),
                "returned_exam_key": str(returned_keys[idx]),
                "expected_exam_key": str(expected_keys[idx]),
            })

        raise RuntimeError(
            "exam_key order mismatch between DataLoader output and df_test.\n"
            "Predictions would be assigned to the wrong metadata rows.\n"
            f"Number of mismatches: {len(mismatch_idx)}\n"
            f"First mismatches: {examples}\n"
            "Please check DataLoader shuffle/order and Dataset indexing."
        )

    log(logf, "  exam_key order check passed: DataLoader output matches df_test order.")

    log(logf, f"  Inference done: {len(y_true)} samples  elapsed={elapsed:.2f}s")
    log(logf, f"  logit range [{logits_uncal.min():.3f}, {logits_uncal.max():.3f}]  "
              f"mean={logits_uncal.mean():.3f}")

    # ── Step 5: Temperature Scaling ───────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, f"Step 5: Temperature Scaling (T*={temperature:.6f})")

    logits_calib, prob_calib = apply_temperature_scaling(logits_uncal, temperature)
    prob_uncal = sigmoid(logits_uncal)

    log(logf, f"  prob_uncal [{prob_uncal.min():.3f}, {prob_uncal.max():.3f}]  "
              f"mean={prob_uncal.mean():.3f}")
    log(logf, f"  prob_calib [{prob_calib.min():.3f}, {prob_calib.max():.3f}]  "
              f"mean={prob_calib.mean():.3f}")

    # ── Step 6: Metrics ───────────────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 6: Compute metrics")

    metrics, bins_uncal, bins_calib = compute_all_metrics(
        y_true, logits_uncal, temperature,
        threshold=THRESHOLD, ece_n_bins=ECE_N_BINS,
    )
    log_summary_table(logf, metrics, model_name)

    # ── Step 7: Plots ─────────────────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 7: Generate plots")

    y_pred_calib = (prob_calib >= THRESHOLD).astype(int)
    title_prefix = f"{model_name.upper()} / {MODALITY} ({IMG_W}×{IMG_H}) / fold {best_fold}"

    plot_confusion_matrix(
        y_true, y_pred_calib,
        os.path.join(out_dir, "confusion_matrix.png"), title_prefix,
    )
    fpr_c, tpr_c, roc_thr_c = plot_roc_curve(
        y_true, prob_uncal, prob_calib,
        os.path.join(out_dir, "roc_curve.png"),
        f"ROC Curve — {title_prefix}",
    )
    pre_c, rec_c, pr_thr_c = plot_pr_curve(
        y_true, prob_uncal, prob_calib,
        os.path.join(out_dir, "pr_curve.png"),
        f"Precision-Recall Curve — {title_prefix}",
    )
    plot_reliability_diagram(
        bins_uncal, bins_calib,
        metrics["ece_uncal"], metrics["ece_calib"],
        os.path.join(out_dir, "reliability_diagram.png"),
        f"Reliability Diagram — {title_prefix}",
    )
    log(logf, "  Plots saved.")

    # ── Step 8: Save data files ───────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 8: Save data files")

    run_cfg = {
        "INPUT_DIR":           INPUT_DIR,
        "model_name":          model_name,
        "timm_backbone":       TIMM_MODEL_MAP[model_name],
        "num_classes":         1,
        "modality":            MODALITY,
        "img_size":            f"{IMG_W}x{IMG_H}",
        "run_tag":             run_tag,
        "best_fold":           best_fold,
        "temperature_T*":      f"{temperature:.6f}",
        "nll_before_ts":       nll_before,
        "nll_after_ts":        nll_after,
        "best_val_bce":        fold_summary.get("best_val_bce"),
        "best_val_auc":        fold_summary.get("best_val_auc"),
        "best_epoch":          fold_summary.get("best_epoch"),
        "checkpoint":          ckpt_path,
        "multimodal_manifest": MULTIMODAL_MANIFEST_CSV,
        "split_set_filter":    "test",
        "threshold":           THRESHOLD,
        "ece_n_bins":          ECE_N_BINS,
        "batch_size":          BATCH_SIZE,
        "img_h":               IMG_H,
        "img_w":               IMG_W,
        "device":              str(device),
        "out_dir":             out_dir,
    }

    save_metrics_csv(metrics, os.path.join(out_dir, "test_metrics.csv"))
    save_curve_csv(fpr_c, tpr_c, roc_thr_c, ["fpr", "tpr", "threshold"],
                   os.path.join(out_dir, "roc_data.csv"))
    save_curve_csv(rec_c, pre_c, pr_thr_c, ["recall", "precision", "threshold"],
                   os.path.join(out_dir, "pr_data.csv"))
    save_calibration_csv(bins_uncal, bins_calib,
                         os.path.join(out_dir, "calibration_data.csv"))

    # ★ 修正③：傳入 df_test，保留 source tracing 欄位
    save_test_preds_csv(
        df_test, logits_uncal, temperature,
        os.path.join(out_dir, "test_preds.csv"),
    )
    save_test_summary_json(metrics, run_cfg, fold_summary,
                           os.path.join(out_dir, "test_summary.json"))
    log(logf, "  All data files saved.")
    log(logf, "  test_preds.csv includes: src_oct0_path / src_oct1_path / "
              "chosen_oct_type / src_octa3_path")

    # ── Step 9: Write text report ─────────────────────────────────────────────
    log(logf, "─" * 72)
    log(logf, "Step 9: Write evaluation report")
    write_report(metrics, run_cfg, os.path.join(out_dir, "test_evaluation_report.txt"))

    # ── Done ──────────────────────────────────────────────────────────────────
    log(logf, "=" * 72)
    log(logf, "EVALUATION COMPLETE")
    log(logf, f"  Results : {out_dir}")
    log(logf, f"  [NEXT]  test_preds.csv → meta-learner evaluation")
    log(logf, "=" * 72)

    logf.close()
    gc.collect()


if __name__ == "__main__":
    main()